{"command":"create","path":"/workspace/backend/service.go","file_text":"package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"math"
	"net/http"
	"sort"
	"time"

	"github.com/lib/pq"
)

type serviceInput struct{Origin coordinate `json:"origin"`;OriginType string `json:"originType"`;OriginNodeID string `json:"originNodeId"`;SampleTypeID string `json:"sampleTypeId"`;RequestedAt string `json:"requestedAt"`;DeliveryDeadline string `json:"deliveryDeadline"`;EarliestCollectionAt string `json:"earliestCollectionAt"`;LatestCollectionAt string `json:"latestCollectionAt"`}
type routeEdge struct{ID,From,To string;Minutes int;Cost float64}
type serviceResult struct{Serviceable bool;Reason,LabID,StartNodeID string;Estimated time.Time;Version int;Edges []routeEdge;Cooled bool}
type nodePoint struct{ID,Name string;Lat,Lon,Coverage float64;Handling int;Functions map[string]bool}

func validateServiceInput(in *serviceInput)(time.Time,time.Time,time.Time,error){
	if !validCoord(in.Origin){return time.Time{},time.Time{},time.Time{},asError("invalid_origin","invalid origin coordinate",400)}
	if in.OriginType==""{in.OriginType="home"};if in.OriginType!="home"&&in.OriginType!="clinic"&&in.OriginType!="node"{return time.Time{},time.Time{},time.Time{},asError("invalid_origin_type","invalid origin type",400)};if in.OriginType=="node"&&in.OriginNodeID==""{return time.Time{},time.Time{},time.Time{},asError("invalid_origin","originNodeId is required",400)}
	req,e:=parseTime(in.RequestedAt);if e!=nil{return time.Time{},time.Time{},time.Time{},e};deadline,e:=parseTime(in.DeliveryDeadline);if e!=nil{return time.Time{},time.Time{},time.Time{},e};earliest:=req;if in.EarliestCollectionAt!=""{earliest,e=parseTime(in.EarliestCollectionAt);if e!=nil{return time.Time{},time.Time{},time.Time{},e}};latest:=earliest;if in.LatestCollectionAt!=""{latest,e=parseTime(in.LatestCollectionAt);if e!=nil{return time.Time{},time.Time{},time.Time{},e}}
	if latest.Before(earliest){return time.Time{},time.Time{},time.Time{},asError("invalid_collection_window","latest collection must not precede earliest",400)};if !deadline.After(req)||!deadline.After(earliest){return time.Time{},time.Time{},time.Time{},asError("invalid_deadline","delivery deadline must follow collection",400)};return earliest,latest,deadline,nil
}

func (a *App) serviceability(ctx context.Context,in *serviceInput)(serviceResult,error){
	earliest,_,deadline,e:=validateServiceInput(in);if e!=nil{return serviceResult{},e};var version int;if e=a.db.QueryRowContext(ctx,`SELECT published_serviceability_version FROM lablogix.network_meta WHERE singleton`).Scan(&version);e!=nil{return serviceResult{},e}
	res:=serviceResult{Reason:"outside_service_coverage",Version:version}
	var cooled bool;var stActive bool;e=a.db.QueryRowContext(ctx,`SELECT requires_cooled_route,active FROM lablogix.sample_types WHERE id=$1`,in.SampleTypeID).Scan(&cooled,&stActive);if e==sql.ErrNoRows{return res,asError("not_found","sample type not found",404)};if e!=nil{return res,e};res.Cooled=cooled;if !stActive{res.Reason="handling_rules_unsatisfiable";return res,nil}
	rows,e:=a.db.QueryContext(ctx,`SELECT id,name,latitude,longitude,coverage_km,handling_minutes,functions FROM lablogix.locations WHERE active`);if e!=nil{return res,e};defer rows.Close();nodes:=map[string]nodePoint{};for rows.Next(){var n nodePoint;var raw []byte;if e=rows.Scan(&n.ID,&n.Name,&n.Lat,&n.Lon,&n.Coverage,&n.Handling,&raw);e!=nil{return res,e};n.Functions=boolMap(raw);nodes[n.ID]=n}
	start:="";best:=math.MaxFloat64;if in.OriginType=="node"{if n,ok:=nodes[in.OriginNodeID];ok{start=n.ID;best=0}}else{for _,n:=range nodes{if !n.Functions["collection_point"]{continue};d:=haversine(in.Origin.Latitude,in.Origin.Longitude,n.Lat,n.Lon);if d<=5&&d<=n.Coverage&&d<best{best,start=d,n.ID}}};if start==""{return res,nil};res.StartNodeID=start
	labRows,e:=a.db.QueryContext(ctx,`SELECT l.id FROM lablogix.locations l JOIN lablogix.laboratory_acceptance x ON x.laboratory_id=l.id WHERE l.active AND COALESCE((l.functions->>'laboratory')::boolean,false) AND x.sample_type_id=$1 AND x.accepts`,in.SampleTypeID);if e!=nil{return res,e};labs:=map[string]bool{};for labRows.Next(){var id string;_ =labRows.Scan(&id);labs[id]=true};labRows.Close();if len(labs)==0{res.Reason="no_accepting_laboratory";return res,nil}
	edgeRows,e:=a.db.QueryContext(ctx,`SELECT c.id,c.from_location_id,c.to_location_id,c.travel_minutes,c.cost_units,COALESCE(p.capacity_units-p.reserved_units,0),COALESCE(p.cooled_capacity_units-p.cooled_reserved_units,0),c.cooled FROM lablogix.connections c LEFT JOIN lablogix.capacities p ON p.resource_id=c.id WHERE c.active`);if e!=nil{return res,e};graph:=map[string][]routeEdge{};for edgeRows.Next(){var x routeEdge;var avail,cavail int;var edgeCooled bool;if e=edgeRows.Scan(&x.ID,&x.From,&x.To,&x.Minutes,&x.Cost,&avail,&cavail,&edgeCooled);e!=nil{return res,e};if cooled {if !edgeCooled||cavail<1{continue}} else if avail<1{continue};graph[x.From]=append(graph[x.From],x)};edgeRows.Close()
	type state struct{id string;mins int;edges []routeEdge};q:=[]state{{start,0,nil}};seen:=map[string]int{};var found *state
	for len(q)>0{sort.Slice(q,func(i,j int)bool{return q[i].mins<q[j].mins});cur:=q[0];q=q[1:];if old,ok:=seen[cur.id];ok&&old<=cur.mins{continue};seen[cur.id]=cur.mins;if labs[cur.id]{v:=cur;found=&v;break};for _,x:=range graph[cur.id]{n:=nodes[x.To];extra:=x.Minutes+n.Handling;es:=append(append([]routeEdge{},cur.edges...),x);q=append(q,state{x.To,cur.mins+extra,es})}}
	if found==nil{res.Reason="no_route";return res,nil}
	for _,id:=range append([]string{start},edgeDestinations(found.edges)...){var regular,cooledAvail int;e=a.db.QueryRowContext(ctx,`SELECT capacity_units-reserved_units,cooled_capacity_units-cooled_reserved_units FROM lablogix.capacities WHERE resource_id=$1`,id).Scan(&regular,&cooledAvail);if e!=nil||(cooled&&cooledAvail<1)||(!cooled&&regular<1){res.Reason="insufficient_capacity";return res,nil}}
