func (a *App) acceptAssignment(w http.ResponseWriter,r *http.Request,s *Session){if !s.hasRole("collection_professional","delivery_partner","node_handler","laboratory_team"){fail(w,403,"ineligible_worker","active role is not a worker role");return};var in struct{AssignmentID string `json:"assignmentId"`;IdempotencyKey string `json:"idempotencyKey"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};var worker,status,kind string;var expiry time.Time;err:=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(offered_worker_id::text,''),status,kind,offer_expires_at FROM lablogix.assignments WHERE id=$1 FOR UPDATE`,in.AssignmentID).Scan(&worker,&status,&kind,&expiry);if err==sql.ErrNoRows{fail(w,404,"not_found","assignment not found");return};if err!=nil{handleErr(w,err);return};expected:=map[string]string{"collection":"collection_professional","transport":"delivery_partner","node":"node_handler","laboratory":"laboratory_team"}[kind];if s.ActiveRole!=expected{fail(w,403,"ineligible_worker","active role is not eligible");return};if worker!=s.UserID{fail(w,409,"offer_not_offered","assignment was offered to another worker");return};if status=="accepted"{data(w,201,map[string]any{"assignmentId":in.AssignmentID,"workerId":s.UserID,"status":"accepted"});return};if status!="pending"{fail(w,409,"assignment_inactive","assignment is inactive");return};if time.Now().After(expiry){fail(w,409,"offer_not_available","assignment offer expired");return};var available bool;_ =a.db.QueryRowContext(r.Context(),`SELECT available FROM lablogix.users WHERE id=$1`,s.UserID).Scan(&available);if !available{fail(w,409,"worker_unavailable","worker is unavailable");return};_,err=a.db.ExecContext(r.Context(),`UPDATE lablogix.assignments SET worker_id=$2,status='accepted' WHERE id=$1 AND status='pending'`,in.AssignmentID,s.UserID);if err!=nil{handleErr(w,err);return};a.audit(r.Context(),s,"accept_assignment","assignment",in.AssignmentID,true,map[string]any{"workerId":s.UserID});a.event(r.Context(),"assignment.accepted","assignment",in.AssignmentID,map[string]any{"workerId":s.UserID});data(w,201,map[string]any{"assignmentId":in.AssignmentID,"workerId":s.UserID,"status":"accepted"})}

func (a *App) declineAssignment(w http.ResponseWriter,r *http.Request,s *Session){var in struct{AssignmentID,Reason,DeclinedAt,IdempotencyKey string};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};at:=time.Now();var err error;if in.DeclinedAt!=""{at,err=parseTime(in.DeclinedAt);if err!=nil{handleErr(w,err);return}};var offered,status,kind string;var sample,node,lab sql.NullString;err=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(offered_worker_id::text,''),status,kind,sample_id,node_id,laboratory_id FROM lablogix.assignments WHERE id=$1`,in.AssignmentID).Scan(&offered,&status,&kind,&sample,&node,&lab);if err==sql.ErrNoRows{fail(w,404,"not_found","assignment not found");return};if err!=nil{handleErr(w,err);return};if offered!=s.UserID{fail(w,403,"forbidden","only the offered worker may decline");return};if status!="pending"{fail(w,409,"assignment_inactive","assignment is inactive");return};role:=map[string]string{"collection":"collection_professional","transport":"delivery_partner","node":"node_handler","laboratory":"laboratory_team"}[kind];q:=`SELECT id FROM lablogix.users WHERE active AND available AND $1=ANY(roles) AND id<>$2`;args:=[]any{role,s.UserID};if node.Valid{q+=` AND assigned_location_id=$3`;args=append(args,node.String)}else if lab.Valid{q+=` AND assigned_location_id=$3`;args=append(args,lab.String)};q+=` ORDER BY decline_score,created_at LIMIT 1`;var next sql.NullString;_ =a.db.QueryRowContext(r.Context(),q,args...).Scan(&next);_,err=a.db.ExecContext(r.Context(),`UPDATE lablogix.assignments SET offered_worker_id=$2,worker_id=NULL,status='pending',declined_by=$3,declined_at=$4,offer_expires_at=now()+interval '15 minutes' WHERE id=$1`,in.AssignmentID,func()any{if next.Valid{return next.String};return nil}(),s.UserID,at);if err!=nil{handleErr(w,err);return};_,_=a.db.ExecContext(r.Context(),`UPDATE lablogix.users SET decline_score=LEAST(decline_scor