async function api(path: string, options: RequestInit = {}) {
  const token = localStorage.getItem('lablogix_token')
  const res = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(options.headers || {}) } })
  const body = await res.json().catch(() => ({ error: 'The server returned an unreadable response.' }))
  if (!res.ok) throw new Error(body.error || body.code || `Request failed (${res.status})`)
  return body.data ?? body
}

export default function App() {
  const [boot, setBoot] = useState<Bootstrap | null>(null)
  const [loading, setLoading] = useState(Boolean(localStorage.getItem('lablogix_token')))
  const [notice, setNotice] = useState<Notice | null>(null)
  const [page, setPage] = useState('overview')
  const load = async () => { setLoading(true); try { setBoot(await api('/api/ui/bootstrap')); setNotice(null) } catch { localStorage.removeItem('lablogix_token'); setBoot(null) } finally { setLoading(false) } }
  useEffect(() => { if (localStorage.getItem('lablogix_token')) load(); else setLoading(false) }, [])
  const signOut = () => { localStorage.removeItem('lablogix_token'); setBoot(null); setPage('overview'); setNotice(null) }
  if (loading) return <div className="center-screen"><div className="spinner" /><p>Preparing custody workspace…</p></div>
  if (!boot) return <Login onLogin={load} />
  const role = boot.user.activeRole
  if (boot.user.roleSelectionRequired || !role) return <RoleGate boot={boot} onSelected={load} onSignOut={signOut} />
