  const load = async () => { setLoading(true); try { setWork(await api('/api/list-role-work', { method: 'POST', body: JSON.stringify({ role }) })) } finally { setLoading(false) } }
  useEffect(() => { load() }, [role])
  const accept = async (id: string) => { try { await api('/api/accept-assignment', { method: 'POST', body: JSON.stringify({ assignmentId: id, idempotencyKey: uid() }) }); setNotice({ kind: 'success', text: 'Assignment accepted. Custody and progress controls are now available.' }); await load() } catch (e) { setNotice({ kind: 'error', text: (e as Error).message }) } }
  if (loading) return <div className="panel empty">Loading role work…</div>
  const sections = compact ? [{ key: 'pending', title: 'Ready for you' }, { key: 'inProgress', title: 'In progress' }] : [{ key: 'pending', title: 'Pending offers' }, { key: 'inProgress', title: 'Current work' }, { key: 'completed', title: 'Past work' }]
  return <div className="work-columns">{sections.map(s => <section className="panel work-section" key={s.key}><PanelHead title={s.title} subtitle={`${work[s.key]?.length || 0} item${work[s.key]?.length === 1 ? '' : 's'}`} />{!work[s.key]?.length ? <div className="empty-state"><span>✓</span><p>Nothing here right now</p></div> : work[s.key].map((item: any) => <article className="work-card" key={item.assignmentId || item.sampleId || item.journeyId} onClick={() => setSelected(item)}><div className="work-card-top"><span className={`status ${statusTone(item.status)}`}>{pretty(item.status)}</span><small>{pretty(item.kind)}</small></div><strong>{item.sampleId ? `Sample ${short(item.sampleId)}` : `Journey ${short(item.journeyId)}`}</strong><p>{item.assignmentId ? `${pretty(item.kind)} assignment · ${short(item.assignmentId)}` : item.serviceability || item.routeMode}</p><div className="work-meta"><span>{item.deliveryDeadline ? `Due ${fmt(item.deliveryDeadline)}` : `${item.history?.length || 0} timeline updates`}</span><button className="link-button" onClick={e => { e.stopPropagation(); setSelected(item) }}>View details →</button></div>{item.status === 'pending' && item.assignmentId && <button className="primary compact" onClick={e => { e.stopPropagation(); accept(item.assignmentId) }}>Accept assignment</button>}</article>)}</section>)}{selected && <DetailDrawer item={selected} role={role} close={() => setSelected(null)} reload={load} setNotice={setNotice} />}</div>
}

function DetailDrawer({ item, role, close, reload, setNotice }: { item: any; role: string; close: () => void; reload: () => Promise<void>; setNotice: (n: Notice | null) => void }) {
  const [detail, setDetail] = useState<any>(null); const [tab, setTab] = useState('summary'); const sampleId = item.sampleId
  useEffect(() => { if (sampleId) Promise.all([api(`/api/read-sample-state/${sampleId}`), api('/api/read-sample-lifecycle', { method: 'POST', body: JSON.stringify({ sampleId }) })]).then(([state, life]) => setDetail({ state, life })).catch(() => setDetail({ state: item, life: { timeline: item.history || [] } })) }, [sampleId])
  const locationUpdate = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); try { await api('/api/record-worker-location', { method: 'POST', body: JSON.stringify({ assignmentId: item.assignmentId, coordinate: { latitude: Number(f.get('latitude')), longitude: Number(f.get('longitude')) }, sequence: Date.now(), recordedAt: new Date().toISOString() }) }); setNotice({ kind: 'success', text: 'Current location recorded.' }); await reload() } catch (x) { setNotice({ kind: 'error', text: (x as Error).message }) } }
  return <div className="drawer-backdrop" onMouseDown={close}><aside className="drawer" onMouseDown={e => e.stopPropagation()} aria-label="Work details"><button className="drawer-close" aria-label="Close details" onClick={close}>×</button><span className="eyebrow">{pretty(item.kind)} details</span><h2>{sampleId ? `Sample ${short(sampleId)}` : `Journey ${short(item.journeyId)}`}</h2><div className="drawer-tabs"><button className={tab === 'summary' ? 'active' : ''} onClick={() => setTab('summary')}>Summary</button><button className={tab === 'timeline' ? 'active' : ''} onClick={() => setTab('timeline')}>Status timeline</button></div>{tab === 'summary' ? <div className="drawer-body"><div className="detail-grid"><Detail label="Status" value={pretty(detail?.life?.status || item.status)} /><Detail label="Current custodian" value={short(detail?.life?.currentHolderId) || 'Not yet sealed'} /><Detail label="Route progress" value={`${detail?.life?.completedLegIds?.length || 0} legs completed`} /><Detail label="Last location update" value={fmt(detail?.life?.locationRecordedAt || item.locationRecordedAt)} /></div><div className={`freshness ${detail?.life?.locationStale ?? item.locationStale ? 'stale' : 'fresh'}`}><span />{detail?.life?.locationStale ?? item.locationStale ? 'Location is stale' : 'Location is current'}</div>{detail?.life?.exception && <div role="alert" className="exception-card"><strong>Exception flagged</strong><p>{detail.life.exception.reason || detail.life.exception.kind || 'Handling requires review'}</p></div>} {item.destinationCapacity && <CapacityBars capacity={item.destinationCapacity} />}{['collection_professional', 'delivery_partner'].includes(role) && item.assignmentId && <form className="inline-form" onSubmit={locationUpdate}><h3>Record current location</h3><div className="form-row"><label>Latitude<input name="latitude" aria-label="Current latitude" type="number" step="any" defaultValue="12.9716" required /></label><label>Longitude<input name="longitude" aria-label="Current longitude" type="number" step="any" defaultValue="77.5946" required /></label></div><button className="secondary">Record location</button></form>}</div> : <Timeline entries={detail?.life?.timeline || item.history || []} />}</aside></div>
}

function RequestForm({ setNotice, onCreated }: { setNotice: (n: Notice | null) => void; onCreated: () => void }) {
  const [originType, setOriginType] = useState('home'); const [typeId, setTypeId] = useState(sampleTypes[0].id); const [result, setResult] = useState<any>(null); const [busy, setBusy] = useState(false)
  const selected = sampleTypes.find(x => x.id === typeId)!
  const payload = (form: HTMLFormElement) => { const f = new FormData(form); return { origin: { latitude: Number(f.get('latitude')), longitude: Number(f.get('longitude')) }, originType, ...(originType === 'node' ? { originNodeId: String(f.get('originNodeId')) } : {}), sampleTypeId: typeId, requestedAt: new Date().toISOString(), earliestCollectionAt: new Date(String(f.get('earliestCollectionAt'))).toISOString(), latestCollectionAt: new Date(String(f.get('latestCollectionAt'))).toISOString(), deliveryDeadline: new Date(String(f.get('deliveryDeadline'))).toISOString() } }
  const dryRun = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); setBusy(true); try { const x = await api('/api/check-serviceability', { method: 'POST', body: JSON.stringify(payload(e.currentTarget)) }); setResult(x); setNotice({ kind: x.serviceable ? 'success' : 'error', text: x.serviceable ? `Serviceable · estimated arrival ${fmt(x.estimatedArrivalAt)}` : `Not serviceable: ${pretty(x.reason)}` }) } catch (x) { setNotice({ kind: 'error', text: (x as Error).message }) } finally { setBusy(false) } }
  const create = async (form: HTMLFormElement) => { setBusy(true); try { const base = payload(form); const x = await api('/api/create-collection-request', { method: 'POST', body: JSON.stringify({ ...base, containerType: selected.container, temperatureMinC: selected.min, temperatureMaxC: selected.max, incompatibleSampleTypes: typeId === sampleTypes[0].id ? [sampleTypes[1].id] : typeId === sampleTypes[1].id ? [sampleTypes[0].id] : [], idempotencyKey: uid() }) }); setNotice({ kind: 'success', text: `Request created. Sample ${short(x.sampleId)} is now tracked.` }); onCreated() } catch (x) { setNotice({ kind: 'error', text: (x as Error).message }) } finally { setBusy(false) } }
  const d = new Date(); const local = (mins: number) => new Date(d.getTime() + mins * 60000).toISOString().slice(0, 16)
  return <section className="panel form-panel"><div className="form-heading"><div><span className="eyebrow">Collection planning</span><h2>Check serviceability first</h2><p>Validate coverage, route, handling, capacity and deadline without reserving anything.</p></div><span className="step-pill">1 of 1</span></div><form onSubmit={dryRun} id="request-form"><fieldset><legend>Origin</legend><div className="segmented" role="group" aria-label="Origin type">{['home', 'clinic', 'node'].map(x => <button type="button" className={originType === x ? 'active' : ''} onClick={() => setOriginType(x)} key={x}>{pretty(x)}</button>)}</div><div className="form-row"><label>Latitude<input name="latitude" aria-label="Origin latitude" type="number" step="any" defaultValue="12.9784" required /></label><label>Longitude<input name="longitude" aria-label="Origin longitude" type="number" step="any" defaultValue="77.6408" required /></label></div>{originType === 'node' && <label>Origin node ID<input name="originNodeId" aria-label="Origin node ID" defaultValue="20000000-0000-4000-8000-000000000001" required /></label>}</fieldset><fieldset><legend>Sample & timing</legend><label>Sample type<select aria-label="Sample type" value={typeId} onChange={e => setTypeId(e.target.value)}>{sampleTypes.map(x => <option key={x.id} value={x.id}>{x.name} · {x.container}</option>)}</select></label><div className="form-row three"><label>Earliest collection<input name="earliestCollectionAt" aria-label="Earliest collection" type="datetime-local" defaultValue={local(30)} required /></label><label>Latest collection<input name="latestCollectionAt" aria-label="Latest collection" type="datetime-local" defaultValue={local(90)} required /></label><label>Delivery deadline<input name="deliveryDeadline" aria-label="Delivery deadline" type="datetime-local" defaultValue={local(300)} required /></label></div></fieldset><div className="dry-note"><span>◇</span><p><strong>Dry run only</strong><br />No request, sample, assignment, journey, or capacity reservation is created by this check.</p></div><div className="form-actions"><button className="secondary" disabled={busy} type="submit">{busy ? 'Checking…' : 'Check serviceability'}</button><button className="primary" disabled={busy || !result?.serviceable} type="button" onClick={() => create(document.getElementById('request-form') as HTMLFormElement)}>Create collection request →</button></div></form></section>
}

function Network() { const [ops, setOps] = useState<any>(null); useEffect(() => { api('/api/read-operations-state', { method: 'POST', body: JSON.stringify({ filters: {} }) }).then(setOps) }, []); if (!ops) return <div className="panel empty">Loading live network…</div>; return <><section className="panel map-panel large"><PanelHead title="Live operations map" subtitle="Latest reported positions and configured network connections" badge="Local map" /><LocalMap operations={ops} /></section><section className="metric-grid"><Metric label="Samples" value={ops.samples.length} tone="teal" /><Metric label="Workers" value={ops.workers.length} tone="blue" /><Metric label="Nodes" value={ops.locations.length} tone="amber" /><Metric label="Exceptions" value={ops.exceptions.length} tone="red" /></section></> }

let protocolAdded = false
function LocalMap({ operations }: { operations: any }) { const ref = useRef<HTMLDivElement>(null); const mapRef = useRef<MapLibreMap | null>(null); useEffect(() => { if (!ref.current) return; if (!protocolAdded) { const protocol = new Protocol(); maplibregl.addProtocol('pmtiles', protocol.tile); protocolAdded = true } const map = new maplibregl.Map({ container: ref.current, center: [77.61, 12.965], zoom: 11, attributionControl: false, style: { version: 8, sources: { local: { type: 'vector', url: 'pmtiles:///maps/bangalore.pmtiles' } }, layers: [{ id: 'background', type: 'background', paint: { 'background-color': '#e9efeb' } }, { id: 'water', type: 'fill', source: 'local', 'source-layer': 'water', paint: { 'fill-color': '#b9d9d6' } }, { id: 'land', type: 'fill', source: 'local', 'source-layer': 'landcover', paint: { 'fill-color': '#dce8dc', 'fill-opacity': 0.5 } }, { id: 'roads', type: 'line', source: 'local', 'source-layer': 'transportation', paint: { 'line-color': '#ffffff', 'line-width': 1.8 } }, { id: 'buildings', type: 'fill', source: 'local', 'source-layer': 'building', paint: { 'fill-color': '#d8d8d2', 'fill-outline-color': '#cacac3' } }] } }); map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'bottom-right'); map.addControl(new maplibregl.AttributionControl({ compact: true }), 'bottom-left'); (operations.locations || []).forEach((x: any) => new Marker({ element: markerElement(x.functions?.laboratory ? 'lab' : 'node') }).setLngLat([x.coordinate.longitude, x.coordinate.latitude]).setPopup(new maplibregl.Popup({ offset: 18 }).setHTML(`<strong>${escapeHtml(x.name)}</strong><br><small>${x.active ? 'Active' : 'Inactive'}</small>`)).addTo(map)); (operations.workers || []).filter((x: any) => x.latestLocation).forEach((x: any) => new Marker({ element: markerElement('worker') }).setLngLat([x.latestLocation.longitude, x.latestLocation.latitude]).addTo(map)); mapRef.current = map; return () => { map.remove(); mapRef.current = null } }, [operations]); return <div className="map" ref={ref} aria-label="Live network map using local PMTiles" /> }

function Audit() { const [query, setQuery] = useState(''); const [result, setResult] = useState<any>({ entries: [] }); const search = async (e?: FormEvent) => { e?.preventDefault(); setResult(await api('/api/search-audit-trail', { method: 'POST', body: JSON.stringify({ query, limit: 100, offset: 0, order: 'newest_first' }) })) }; useEffect(() => { search() }, []); return <section className="panel"><PanelHead title="Searchable audit trail" subtitle="Sign-ins, permission decisions, custody, plans, capacity and completion" /><form className="searchbar" onSubmit={search}><label className="sr-only">Search audit history</label><input aria-label="Search audit history" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search action, item ID, or recorded change…" /><button className="secondary">Search</button></form><div className="table-wrap"><table><thead><tr><th>When</th><th>Action</th><th>Actor role</th><th>Affected item</th><th>Outcome</th></tr></thead><tbody>{result.entries.map((x: any) => <tr key={x.auditId}><td>{fmt(x.occurredAt)}</td><td><strong>{pretty(x.action)}</strong></td><td>{roleNames[x.actorRole] || x.actorRole}</td><td>{pretty(x.entityType)} · {short(x.entityId)}</td><td><span className={`status ${x.success ? 'green' : 'red'}`}>{x.success ? 'Success' : 'Failed'}</span></td></tr>)}</tbody></table>{!result.entries.length && <div className="empty-state"><p>No matching audit records</p></div>}</div></section> }

function Capacity({ role, setNotice }: { role: string; setNotice: (n: Notice | null) => void }) { const [work, setWork] = useState<any>(null); const [resourceId, setResourceId] = useState(''); useEffect(() => { api('/api/list-role-work', { method: 'POST', body: JSON.stringify({ role }) }).then(x => { setWork(x); const all = [...x.pending, ...x.inProgress, ...x.completed]; setResourceId(all.find((i: any) => i.laboratoryId || i.nodeId)?.laboratoryId || all.find((i: any) => i.nodeId)?.nodeId || '') }) }, [role]); const caps = useMemo(() => work ? [...work.pending, ...work.inProgress, ...work.completed].find((x: any) => x.destinationCapacity)?.destinationCapacity : null, [work]); const save = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); try { await api('/api/configure-capacity', { method: 'POST', body: JSON.stringify({ resourceId: String(f.get('resourceId')), capacityUnits: Number(f.get('regular')), cooledCapacityUnits: Number(f.get('cooled')) }) }); setNotice({ kind: 'success', text: 'Capacity configuration updated.' }) } catch (x) { setNotice({ kind: 'error', text: (x as Error).message }) } }; return <div className="split-layout"><section className="panel"><PanelHead title="Assigned capacity" subtitle="Configured, reserved and available units" />{caps ? <CapacityBars capacity={caps} /> : <div className="empty-state"><p>No assigned capacity is visible yet.</p></div>}</section><section className="panel"><PanelHead title="Configure capacity" subtitle="Reservations can never be overbooked" /><form className="stack-form" onSubmit={save}><label>Resource ID<input name="resourceId" aria-label="Capacity resource ID" value={resourceId} onChange={e => setResourceId(e.target.value)} required /></label><div className="form-row"><label>Regular units<input name="regular" aria-label="Regular capacity units" type="number" min="0" defaultValue="40" required /></label><label>Cooled units<input name="cooled" aria-label="Cooled capacity units" type="number" min="0" defaultValue="12" required /></label></div><button className="primary">Save capacity</button></form></section></div> }

function Administration({ setNotice }: { setNotice: (n: Notice | null) => void }) { const [tab, setTab] = useState('users'); const submitUser = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); try { const role = String(f.get('role')); await api('/api/create-user', { method: 'POST', body: JSON.stringify({ username: f.get('username'), initialPassword: f.get('password'), fullName: f.get('fullName'), roles: [role], qualifications: role === 'collection_professional' ? sampleTypes.map(x => x.name) : [], certifications: [], active: true, ...(f.get('assignedLocationId') ? { assignedLocationId: f.get('assignedLocationId') } : {}) }) }); setNotice({ kind: 'success', text: 'User created and role access assigned.' }); e.currentTarget.reset() } catch (x) { setNotice({ kind: 'error', text: (x as Error).message }) } }; return <section className="panel form-panel"><div className="admin-tabs"><button className={tab === 'users' ? 'active' : ''} onClick={() => setTab('users')}>Users & roles</button><button className={tab === 'network' ? 'active' : ''} onClick={() => setTab('network')}>Network configuration</button><button className={tab === 'samples' ? 'active' : ''} onClick={() => setTab('samples')}>Sample types</button></div>{tab === 'users' && <form className="stack-form narrow" onSubmit={submitUser}><PanelHead title="Onboard a user" subtitle="Assign current roles, certifications and facility scope" /><label>Full name<input name="fullName" aria-label="Full name" required /></label><div className="form-row"><label>Username<input name="username" aria-label="New username" required /></label><label>Initial password<input name="password" aria-label="Initial password" type="password" minLength={8} required /></label></div><label>Role<select name="role" aria-label="Assigned role">{Object.entries(roleNames).map(([id, name]) => <option value={id} key={id}>{name}</option>)}</select></label><label>Assigned node or laboratory ID <small>(facility roles)</small><input name="assignedLocationId" aria-label="Assigned location ID" /></label><button className="primary">Create user</button></form>}{tab === 'network' && <div className="empty-state roomy"><span>⌘</span><h3>Network configuration is API-ready</h3><p>Create and update locations, functions, connections, coverage, handling times and laboratory acceptance through the documented administrator API.</p></div>}{tab === 'samples' && <div className="sample-type-grid">{sampleTypes.map(x => <article key={x.id}><span className={`sample-dot ${x.name.toLowerCase()}`} /><strong>{x.name}</strong><p>{x.container} · {x.min}–{x.max}°C</p><small>{short(x.id)}</small></article>)}</div>}</section> }

function Timeline({ entries }: { entries: any[] }) { return <ol className="timeline">{entries.length ? entries.map((x, i) => <li key={x.eventId || i}><span /><div><strong>{pretty(x.action)}</strong><p>{pretty(x.role)} · {x.success ? 'Successful' : 'Failed'}</p><time>{fmt(x.occurredAt)}</time></div></li>) : <li><span /><div><strong>No status updates yet</strong><p>Events will appear in chronological order.</p></div></li>}</ol> }
function CapacityBars({ capacity: c }: { capacity: any }) { const row = (name: string, total: number, reserved: number, tone: string) => <div className="capacity-row"><div><strong>{name}</strong><span>{total - reserved} available · {reserved} reserved · {total} configured</span></div><div className="bar"><i className={tone} style={{ width: `${total ? Math.min(100, reserved / total * 100) : 0}%` }} /></div></div>; return <div className="capacity-bars">{row('Regular', c.capacityUnits, c.reservedUnits, 'regular')}{row('Cooled', c.cooledCapacityUnits, c.cooledReservedUnits, 'cooled')}</div> }
function Attention({ operations }: { operations: any }) { const items = [...(operations.exceptions || []).map((x: any) => ({ ...x, text: x.reason, tone: 'red' })), ...(operations.handoffs || []).map((x: any) => ({ ...x, text: `Handoff pending for ${short(x.sampleId)}`, tone: 'amber' }))]; return <div className="attention-list">{items.length ? items.slice(0, 5).map((x: any, i: number) => <div key={x.exceptionId || x.handoffId || i}><span className={x.tone}>!</span><p><strong>{x.text}</strong><small>Sample {short(x.sampleId)}</small></p></div>) : <div className="empty-state"><span>✓</span><p>No immediate exceptions</p></div>}</div> }
function Metric({ label, value, tone }: { label: string; value: number; tone: string }) { return <article className={`metric ${tone}`}><span className="metric-icon">{tone === 'red' ? '!' : tone === 'amber' ? '↔' : tone === 'blue' ? '♙' : '◇'}</span><div><strong>{value}</strong><p>{label}</p></div><small>Live</small></article> }
function Category({ name, count }: { name: string; count: number }) { return <div><strong>{count}</strong><span>{name}</span></div> }
function PanelHead({ title, subtitle, badge }: { title: string; subtitle?: string; badge?: string }) { return <div className="panel-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{badge && <span className="live-badge"><i />{badge}</span>}</div> }
function Detail({ label, value }: { label: string; value: string }) { return <div><small>{label}</small><strong>{value}</strong></div> }
function Logo() { return <span className="logo-mark" aria-hidden="true"><i /><i /><i /></span> }
function roleIcon(r: string) { return ({ administrator: '⚙', dispatcher: '⌘', requester: '◇', collection_professional: '✚', delivery_partner: '→', node_handler: '⬡', laboratory_team: '⌂' } as any)[r] || '•' }
function pageTitle(p: string) { return ({ overview: 'Operations overview', work: 'Current & past work', request: 'New collection request', network: 'Network monitor', audit: 'Audit trail', capacity: 'Capacity control', admin: 'Administration' } as any)[p] || 'Workspace' }
function initials(s: string) { return s.split(/\s+/).map(x => x[0]).join('').slice(0, 2).toUpperCase() }
function pretty(s?: string) { return (s || 'unknown').replaceAll('_', ' ').replace(/\b\w/g, x => x.toUpperCase()) }
function short(s?: string) { return s ? s.slice(0, 8) : '' }
function statusTone(s: string) { if (['received', 'completed', 'accepted', 'serviceable'].includes(s)) return 'green'; if (['exception', 'expired', 'cancelled'].includes(s)) return 'red'; if (['pending', 'requested'].includes(s)) return 'amber'; return 'blue' }
function markerElement(kind: string) { const el = document.createElement('div'); el.className = `map-marker ${kind}`; el.textContent = kind === 'lab' ? '+' : kind === 'worker' ? '•' : '◇'; return el }
function escapeHtml(s: string) { return s.replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[c] || c)) }
