func (a *App) withIdempotency(w http.ResponseWriter, r *http.Request, s *Session, operation string, fn func(http.ResponseWriter, *http.Request, *Session)) {
	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 1<<20))
	if err != nil {
		fail(w, 400, "invalid_json", "invalid request body")
		return
	}
	r.Body = io.NopCloser(bytes.NewReader(body))
	var envelope map[string]json.RawMessage
	if json.Unmarshal(body, &envelope) != nil {
		fn(w, r, s)
		return
	}
	var key string
	if raw, ok := envelope["idempotencyKey"]; !ok || json.Unmarshal(raw, &key) != nil || key == "" {
		fn(w, r, s)
		return
	}
	hash := fmt.Sprintf("%x", sha256.Sum256(body))
	conn, err := a.db.Conn(r.Context())
	if err != nil {
		handleErr(w, err)
		return
	}
	defer conn.Close()
	lockKey := s.UserID + "|" + operation + "|" + key
	if _, err = conn.ExecContext(r.Context(), `SELECT pg_advisory_lock(hashtextextended($1,0))`, lockKey); err != nil {
		handleErr(w, err)
		return
	}
	defer conn.ExecContext(context.Background(), `SELECT pg_advisory_unlock(hashtextextended($1,0))`, lockKey)
	var storedHash string
	var status int
	var response []byte
	err = conn.QueryRowContext(r.Context(), `SELECT request_hash,status_code,response::text FROM lablogix.idempotency_records WHERE actor_id=$1 AND operation=$2 AND idempotency_key=$3`, s.UserID, operation, key).Scan(&storedHash, &status, &response)
	if err == nil {
		if storedHash != hash {
			fail(w, 409, "idempotency_conflict", "idempotency key was used with a different request")
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(response)
		return
	}
	if err != sql.ErrNoRows {
		handleErr(w, err)
		return
	}
	recorder := httptest.NewRecorder()
	fn(recorder, r, s)
	result := recorder.Result()
	response, _ = io.ReadAll(result.Body)
	for name, values := range result.Header {
		for _, value := range values {
			w.Header().Add(name, value)
		}
	}
	if result.StatusCode >= 200 && result.StatusCode < 300 {
		if _, err = conn.ExecContext(r.Context(), `INSERT INTO lablogix.idempotency_records(actor_id,operation,idempotency_key,request_hash,status_code,response) VALUES($1,$2,$3,$4,$5,$6::jsonb)`, s.UserID, operation, key, hash, result.StatusCode, response); err != nil {
			handleErr(w, err)
			return
		}
	}
	w.WriteHeader(result.StatusCode)
	_, _ = w.Write(response)
}

